#include "dsp_probe_workload.h"
#include <cstdio>
int main(){std::printf("{\"revision\":2,\"stress_start\":%u,\"cases\":[",groove::dsp_stress_start());for(unsigned i=0;i<groove::dsp_case_count();++i){auto c=groove::dsp_condition(i);auto* d=groove::engine_descriptor(unsigned(c.engine));unsigned cost=groove::engine_voice_cost(c.engine,c.variant),native_avg=0,native_burst=0;if(d->runtime_cost.values && c.variant<d->runtime_cost.count){auto v=d->runtime_cost.values[c.variant];native_avg=v.average_us;native_burst=v.burst_us;}std::printf("%s{\"case\":%u,\"kind\":%u,\"engine\":%u,\"name\":\"%s\",\"variant\":%u,\"tracks\":%u,\"notes\":%u,\"declared_cost\":%u,\"independent\":%s,\"native_avg_us\":%u,\"native_burst_us\":%u}",i?",":"",i,unsigned(c.kind),unsigned(c.engine),d->instrument.name,c.variant,c.tracks,c.notes,cost,d->polyphony.independent_voices?"true":"false",native_avg,native_burst);}std::puts("]}");}
